llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C28"],
      "claim": "In male patients with alcoholic cirrhosis, meperidine oral bioavailability was 0.80 ± 0.15 versus 0.57 ± 0.12 in normal controls, demonstrating that cirrhosis can markedly increase the oral bioavailability of a high-extraction drug; this condition-matched evidence supports F ≥20% for the query in cirrhosis.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Flupirtine, a fluorophenyl heteroaromatic drug, has an absolute oral bioavailability of 90% in healthy volunteers, supporting that the query's fluorophenyl/ester/amide class can be well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Lemborexant, a fused heteroaromatic amide with fluorophenyl groups, has at least 87% oral bioavailability in healthy subjects, supporting high oral F for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "A low-similarity pyrrole-amide analogue had ~10% oral bioavailability due to very slow absorption; this is weak contradictory evidence because the mechanism (poor absorption) and condition (healthy subjects) differ from the query's expected first-pass limitation in cirrhosis.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is flumazenil, a high-extraction benzodiazepine antagonist. Although healthy-subject oral bioavailability is typically low, cirrhosis impairs first-pass metabolism; the condition-matched meperidine data and the preponderance of high-F analogues support F ≥20% in cirrhosis.",
  "evidence_gaps": [
    "No direct flumazenil bioavailability record in cirrhosis is present.",
    "All retrieved analogues have low Morgan similarity (<0.26), limiting quantitative transfer.",
    "Most high-F evidence is from healthy subjects rather than cirrhosis."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

